def align_up(value: int, alignment: int) -> int:
    if not (0 <= value <= 65535) or not (0 <= alignment <= 65535):
        return -1
    if alignment <= 0 or (alignment & (alignment - 1)) != 0:
        return -1
    remainder = value % alignment
    if remainder == 0:
        result = value
    else:
        result = value + (alignment - remainder)
    if result > 65535:
        return -1
    return result
